type VrfRouteListType = {
  routes?: z.infer<typeof VrfRouteSchema>[]
  meta?: z.infer<typeof MetaSchema>
}

type VrfVirtualCircuitStatusType =
  | 'pending'
  | 'waiting_on_peering_details'
  | 'activating'
  | 'changing_peering_details'
  | 'deactivating'
  | 'deleting'
  | 'active'
  | 'expired'
  | 'activation_failed'
  | 'changing_peering_details_failed'
  | 'deactivation_failed'
  | 'delete_failed'

const VrfVirtualCircuitStatusSchema: z.ZodType<VrfVirtualCircuitStatusType> = z
  .enum([
    'pending',
    'waiting_on_peering_details',
    'activating',
    'changing_peering_details',
    'deactivating',
    'deleting',
    'active',
    'expired',
    'activation_failed',
    'changing_peering_details_failed',
    'deactivation_failed',
    'delete_failed',
  ])
  .openapi({
    description:
      "The status changes of a VRF virtual circuit are generally the same as Virtual Circuits that aren't in a VRF. However, for VRF Virtual Circuits on Fabric VCs, the status will change to 'waiting_on_peering_details' once the Fabric service token associated with the virtual circuit has been redeemed on Fabric, and Metal has found the associated Fabric connection. At this point, users can update the subnet, MD5 password, customer IP and/or metal IP accordingly. For VRF Virtual Circuits on Dedicated Ports, we require all peering details to be set on creation of a VRF Virtual Circuit. The status will change to `changing_peering_details` whenever an active VRF Virtual Circuit has any of its peering details updated.",
  })
  .openapi('VrfVirtualCircuitStatus')

type VrfVirtualCircuitType = {
  customer_ip?: string
  description?: string
  id?: string
  md5?: string
  metal_ip?: string
  name?: string
  port?: z.infer<typeof HrefSchema>
  nni_vlan?: number
  peer_asn?: number
  project?: z.infer<typeof HrefSchema>
  speed?: number
  status?: z.infer<typeof VrfVirtualCircuitStatusSchema>
  subnet?: string
  tags?: string[]
  type?: z.infer<typeof VrfIpReservationTypeSchema>
  vrf: z.infer<typeof VrfSchema>
  created_at?: string
  updated_at?: string
}

