const BgpRouteSchema = z
  .object({
    exact: z.boolean().exactOptional(),
    route: z.string().exactOptional().openapi({ example: '10.32.16.0/31' }),
  })
  .openapi({ required: [] })
  .openapi('BgpRoute')

const BgpNeighborDataSchema = z
  .object({
    address_family: z
      .int32()
      .exactOptional()
      .openapi({
        description: 'Address Family for IP Address. Accepted values are 4 or 6',
        example: 4,
      }),
    customer_as: z
      .int32()
      .exactOptional()
      .openapi({
        description:
          "The customer's ASN. In a local BGP deployment, this will be an internal ASN used to route within the data center. For a global BGP deployment, this will be the your own ASN, configured when you set up BGP for your project.",
        example: 65000,
      }),
    customer_ip: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The device's IP address. For an IPv4 BGP session, this is typically the private bond0 address for the device.",
        example: '10.32.16.1 (IPv4) or 2604:1380:4111:2700::1 (IPv6)',
      }),
    md5_enabled: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'True if an MD5 password is configured for the project.' }),
    md5_password: z
      .string()
      .exactOptional()
      .openapi({ description: 'The MD5 password configured for the project, if set.' }),
    multihop: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'True when the BGP session should be configured as multihop.' }),
    peer_as: z
      .int32()
      .exactOptional()
      .openapi({
        description: 'The Peer ASN to use when configuring BGP on your device.',
        example: 65530,
      }),
    peer_ips: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'A list of one or more IP addresses to use for the Peer IP section of your BGP configuration. For non-multihop sessions, this will typically be a single gateway address for the device. For multihop sessions, it will be a list of IPs.',
        example: ['169.254.255.1', '169.254.255.2'],
      }),
    routes_in: z
      .array(BgpRouteSchema)
      .exactOptional()
      .openapi({
        description: 'A list of project subnets',
        example: [{ exact: true, route: '10.32.16.0/31' }],
      }),
    routes_out: z
      .array(BgpRouteSchema)
      .exactOptional()
      .openapi({
        description:
          'A list of outgoing routes. Only populated if the BGP session has default route enabled.',
        example: [{ exact: true, route: '0.0.0.0/0' }],
      }),
  })
  .openapi({
    example: {
      md5_password: 'md5_password',
      customer_as: 65000,
      address_family: 4,
      routes_in: [{ exact: true, route: '10.32.16.0/31' }],
      customer_ip: '10.32.16.1 (IPv4) or 2604:1380:4111:2700::1 (IPv6)',
      multihop: true,
      peer_as: 65530,
      md5_enabled: true,
      peer_ips: ['169.254.255.1', '169.254.255.2'],
      routes_out: [{ exact: true, route: '0.0.0.0/0' }],
    },
    required: [],
  })
  .openapi('BgpNeighborData')

