const VlanVirtualCircuitCreateInputSchema = z
  .object({
    description: z.string().exactOptional(),
    name: z.string().exactOptional(),
    nni_vlan: z.int().min(2).max(4094).exactOptional(),
    project_id: z.uuid(),
    speed: z
      .int()
      .exactOptional()
      .openapi({
        description:
          "speed can be passed as integer number representing bps speed or string (e.g. '52m' or '100g' or '4 gbps')",
      }),
    tags: z.array(z.string()).exactOptional(),
    vnid: z
      .uuid()
      .exactOptional()
      .openapi({
        description:
          'A Virtual Network record UUID or the VNID of a Metro Virtual Network in your project (sent as integer).',
      }),
  })
  .openapi({ required: ['project_id'] })
  .openapi('VlanVirtualCircuitCreateInput')

const VrfVirtualCircuitCreateInputSchema = z
  .object({
    customer_ip: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'An IP address from the subnet that will be used on the Customer side. This parameter is optional, but if supplied, we will use the other usable IP address in the subnet as the Metal IP. By default, the last usable IP address in the subnet will be used.',
        example: '12.0.0.2',
      }),
    description: z.string().exactOptional(),
    md5: z
      .string()
      .regex(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)[a-zA-Z\d]{10,20}$/)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The plaintext BGP peering password shared by neighbors as an MD5 checksum:\n* must be 10-20 characters long\n* may not include punctuation\n* must be a combination of numbers and letters\n* must contain at least one lowercase, uppercase, and digit character\n',
      }),
    metal_ip: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'An IP address from the subnet that will be used on the Metal side. This parameter is optional, but if supplied, we will use the other usable IP address in the subnet as the Customer IP. By default, the first usable IP address in the subnet will be used.',
        example: '12.0.0.1',
      }),
    name: z.string().exactOptional(),
    nni_vlan: z.int().min(2).max(4094),
    peer_asn: z
      .int()
      .openapi({
        description: 'The peer ASN that will be used with the VRF on the Virtual Circuit.',
      }),
    project_id: z.uuid(),
    speed: z
      .int()
      .exactOptional()
      .openapi({
        description:
          "speed can be passed as integer number representing bps speed or string (e.g. '52m' or '100g' or '4 gbps')",
      }),
    subnet: z
      .string()
      .openapi({
        description:
          'The /30 or /31 subnet of one of the VRF IP Blocks that will be used with the VRF for the Virtual Circuit. This subnet does not have to be an existing VRF IP reservation, as we will create the VRF IP reservation on creation if it does not exist. The Metal IP and Customer IP must be IPs from this subnet. For /30 subnets, the network and broadcast IPs cannot be used as the Metal or Customer IP. The subnet specified must be contained within an already-defined IP Range for the VRF.',
        example: '12.0.0.0/30',
      }),
    tags: z.array(z.string()).exactOptional(),
    vrf: z
      .uuid()
      .openapi({
        description: 'The UUID of the VRF that will be associated with the Virtual Circuit.',
      }),
  })
  .openapi({ required: ['nni_vlan', 'peer_asn', 'project_id', 'subnet', 'vrf'] })
  .openapi('VrfVirtualCircuitCreateInput')

const VirtualCircuitCreateInputSchema = z
