const VlanFabricVcCreateInputServiceTokenTypeSchema = z
  .enum(['a_side', 'z_side'])
  .openapi({
    description:
      "Either 'a_side' or 'z_side'. Setting this field to 'a_side' will create an interconnection with Fabric VCs (Metal Billed). Setting this field to 'z_side' will create an interconnection with Fabric VCs (Fabric Billed). This is required when the 'type' is 'shared', but this is not applicable when the 'type' is 'dedicated'. This parameter is included in the specification as a developer preview and is generally unavailable. Please contact our Support team for more details.",
    example: 'a_side',
  })
  .openapi('VlanFabricVcCreateInputServiceTokenType')

const VlanFabricVcCreateInputTypeSchema = z
  .literal('shared')
  .openapi({
    description: "When requesting for a Fabric VC, the value of this field should be 'shared'.",
  })
  .openapi('VlanFabricVcCreateInputType')

const VlanFabricVcCreateInputSchema = z
  .object({
    contact_email: z
      .email()
      .exactOptional()
      .openapi({
        description:
          'The preferred email used for communication and notifications about the Equinix Fabric interconnection. Required when using a Project API key. Optional and defaults to the primary user email address when using a User API key.',
      }),
    description: z.string().exactOptional(),
    metro: z
      .string()
      .openapi({
        description:
          'A Metro ID or code. When creating Fabric VCs (Metal Billed), this is where interconnection will be originating from, as we pre-authorize the use of one of our shared ports as the origin of the interconnection using A-Side service tokens. We only allow local connections for Fabric VCs (Metal Billed), so the destination location must be the same as the origin. For Fabric VCs (Fabric Billed), or shared connections, this will be the destination of the interconnection. We allow remote connections for Fabric VCs (Fabric Billed), so the origin of the interconnection can be a different metro set here.',
      }),
    name: z.string(),
    project: z.string().exactOptional(),
    redundancy: z.string().openapi({ description: "Either 'primary' or 'redundant'." }),
    service_token_type: VlanFabricVcCreateInputServiceTokenTypeSchema,
    speed: z
      .int()
      .exactOptional()
      .openapi({
        description:
          "A interconnection speed, in bps, mbps, or gbps. For Fabric VCs, this represents the maximum speed of the interconnection. For Fabric VCs (Metal Billed), this can only be one of the following: \n''50mbps'', ''200mbps'', ''500mbps'', ''1gbps'', ''2gbps'', ''5gbps'' or ''10gbps'', and is required for creation. For Fabric VCs (Fabric Billed), this field will always default to ''10gbps'' even if it is not provided.\nFor example, ''500000000'', ''50m'', or' ''500mbps'' will all work as valid inputs.",
        example: 10000000000,
      }),
    tags: z.array(z.string()).exactOptional(),
    type: VlanFabricVcCreateInputTypeSchema,
    vlans: z
      .array(z.int())
      .exactOptional()
      .openapi({
        description:
          'A list of one or two metro-based VLANs that will be set on the virtual circuits of primary and/or secondary (if redundant) interconnections respectively when creating Fabric VCs. VLANs can also be set after the interconnection is created, but are required to fully activate the virtual circuits.',
        example: [1000, 1001],
      }),
  })
  .openapi({ required: ['metro', 'name', 'redundancy', 'service_token_type', 'type'] })
  .openapi('VlanFabricVcCreateInput')

