const PageParamsSchema = z
  .preprocess(
    (val) =>
      typeof val === 'string' &&
      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
        ? Number(val)
        : val,
    z.int32().min(1).max(100000),
  )
  .default(1)
  .exactOptional()
  .openapi({
    param: {
      description: 'Page to return',
      in: 'query',
      name: 'page',
      schema: { default: 1, format: 'int32', maximum: 100000, minimum: 1, type: 'integer' },
      required: false,
    },
  })

const PerPageParamsSchema = z
