export const getProjectsIdDevicesRoute = createRoute({
  method: 'get',
  path: '/projects/{id}/devices',
  tags: ['Devices'],
  summary: 'Retrieve all devices of a project',
  description: 'Provides a collection of devices for a given project.',
  operationId: 'findProjectDevices',
  request: {
    params: z.object({
      id: z
        .uuid()
        .openapi({
          param: {
            description: 'Project UUID',
            in: 'path',
            name: 'id',
            required: true,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
    }),
    query: z.object({
      search: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Search by hostname, description, short_id, reservation short_id, tags, plan name, plan slug, facility code, facility name, operating system name, operating system slug, IP addresses.',
            in: 'query',
            name: 'search',
            schema: { type: 'string' },
            required: false,
          },
        }),
      categories: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(FindOrganizationDevicesCategoriesParameterInnerSchema),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by plan category',
            in: 'query',
            name: 'categories',
            schema: {
              items: {
                $ref: '#/components/schemas/findOrganizationDevices_categories_parameter_inner',
              },
              type: 'array',
            },
            required: false,
          },
        }),
      facility: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by device facility',
            in: 'query',
            name: 'facility',
            schema: { type: 'string' },
            required: false,
          },
        }),
      metro: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by device metro',
            in: 'query',
            name: 'metro',
            schema: { type: 'string' },
            required: false,
          },
        }),
      hostname: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by partial hostname',
            in: 'query',
            name: 'hostname',
            schema: { type: 'string' },
            required: false,
          },
        }),
      reserved: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter only reserved instances. When set to true, only include reserved instances. When set to false, only include on-demand instances.',
            in: 'query',
            name: 'reserved',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      tag: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by device tag',
            in: 'query',
            name: 'tag',
            schema: { type: 'string' },
            required: false,
          },
        }),
      type: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by instance type (ondemand,spot,reserved)',
            in: 'query',
            name: 'type',
            schema: { type: 'string' },
            required: false,
          },
        }),
      has_termination_time: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter only instances marked for termination. When set to true, only include instances that have a termination time. When set to false, only include instances that do not have a termination time.',
            in: 'query',
            name: 'has_termination_time',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      include: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Nested attributes to include. Included objects will return their full\nattributes. Attribute names can be dotted (up to 3 levels) to included deeply\nnested objects.',
            explode: false,
            in: 'query',
            name: 'include',
            schema: { items: { type: 'string' }, type: 'array' },
            style: 'form',
            required: false,
          },
        }),
      exclude: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Nested attributes to exclude. Excluded objects will return only the href\nattribute. Attribute names can be dotted (up to 3 levels) to exclude deeply\nnested objects.',
            explode: false,
            in: 'query',
            name: 'exclude',
            schema: { items: { type: 'string' }, type: 'array' },
            style: 'form',
            required: false,
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(100000),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            description: 'Page to return',
            in: 'query',
            name: 'page',
            schema: { default: 1, format: 'int32', maximum: 100000, minimum: 1, type: 'integer' },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(1000),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            description: 'Items returned per page',
            in: 'query',
            name: 'per_page',
            schema: { default: 10, format: 'int32', maximum: 1000, minimum: 1, type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: { description: 'ok', content: { 'application/json': { schema: DeviceListSchema } } },
    401: { description: 'unauthorized', content: { 'application/json': { schema: ErrorSchema } } },
    403: { description: 'forbidden', content: { 'application/json': { schema: ErrorSchema } } },
    404: { description: 'not found', content: { 'application/json': { schema: ErrorSchema } } },
  },
})

