export const getUsersRoute = createRoute({
  method: 'get',
  path: '/users',
  tags: ['Users'],
  summary: 'Retrieve all users',
  description:
    'Returns a list of users that the are accessible to the current user (all users in the current user’s projects, essentially).',
  operationId: 'findUsers',
  request: {
    query: z.object({
      include: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Nested attributes to include. Included objects will return their full\nattributes. Attribute names can be dotted (up to 3 levels) to included deeply\nnested objects.',
            explode: false,
            in: 'query',
            name: 'include',
            schema: { items: { type: 'string' }, type: 'array' },
            style: 'form',
            required: false,
          },
        }),
      exclude: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Nested attributes to exclude. Excluded objects will return only the href\nattribute. Attribute names can be dotted (up to 3 levels) to exclude deeply\nnested objects.',
            explode: false,
            in: 'query',
            name: 'exclude',
            schema: { items: { type: 'string' }, type: 'array' },
            style: 'form',
            required: false,
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(100000),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            description: 'Page to return',
            in: 'query',
            name: 'page',
            schema: { default: 1, format: 'int32', maximum: 100000, minimum: 1, type: 'integer' },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(1000),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            description: 'Items returned per page',
            in: 'query',
            name: 'per_page',
            schema: { default: 10, format: 'int32', maximum: 1000, minimum: 1, type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: { description: 'ok', content: { 'application/json': { schema: UserListSchema } } },
    401: { description: 'unauthorized', content: { 'application/json': { schema: ErrorSchema } } },
  },
})

